const CORINGA_LOOKUP = new Map<string, string>();
const FLEET_LOOKUP = new Map<string, string>();

CORINGA_MAPPING.forEach(m => {
  const rawSistema = m.sistema.toUpperCase().replace(/[^A-Z0-9]/g, '');
  const mercSistema = getMercosulPlate(rawSistema);
  const oldSistema = getOldPlate(rawSistema);
  const coringa = m.coringa.toUpperCase().replace(/[^A-Z0-9]/g, '');
  const frota = String(m.frota).trim();
  
  CORINGA_LOOKUP.set(coringa, mercSistema);
  CORINGA_LOOKUP.set(rawSistema, mercSistema);
  CORINGA_LOOKUP.set(mercSistema, mercSistema);
  if (oldSistema) CORINGA_LOOKUP.set(oldSistema, mercSistema);
  
  FLEET_LOOKUP.set(coringa, frota);
  FLEET_LOOKUP.set(rawSistema, frota);
  FLEET_LOOKUP.set(mercSistema, frota);
  if (oldSistema) FLEET_LOOKUP.set(oldSistema, frota);
});

const formatField = (val: any): string => {
  if (val === undefined || val === null) return '-';
  const str = String(val).trim();
  if (str === '' || str === 'N/A' || str === 'Sem Veic' || str === 'UNKNOWN' || str === 'Sem registro' || str === 'Sem Placa' || str === 'undefined' || str === 'null') {
    return '-';
  }
  return str;
};

