const MONTH_NAMES_SHORT = ['JAN', 'FEV', 'MAR', 'ABR', 'MAI', 'JUN', 'JUL', 'AGO', 'SET', 'OUT', 'NOV', 'DEZ'];

const parseMoney = (val: any): number => {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  let s = val.toString().trim();
  
  if (s.toLowerCase().includes('e')) {
    s = s.replace(',', '.');
    const parsed = parseFloat(s);
    return isNaN(parsed) ? 0 : parsed;
  }

  s = s.replace(/[R$\s]/g, '');

  if (s.includes(",") && s.includes(".")) {
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) {
      s = s.replace(/\./g, "").replace(",", ".");
    } else {
      s = s.replace(/,/g, "");
    }
    return parseFloat(s) || 0;
  }
  
  if (s.includes(",") && !s.includes(".")) {
    s = s.replace(",", ".");
    return parseFloat(s) || 0;
  }

  if (s.includes(".")) {
    const dotsCount = s.split(".").length - 1;
    const digitsOnly = s.replace(/\./g, "");
    const lastPart = s.split(".").pop() || "";
    
    if (dotsCount > 1 || (dotsCount === 1 && digitsOnly.length >= 7 && lastPart.length === 3)) {
      if (digitsOnly.length > 6) {
        const intPart = digitsOnly.substring(0, digitsOnly.length - 6);
        const decPart = digitsOnly.substring(digitsOnly.length - 6);
        s = intPart + "." + decPart;
      } else {
        s = "0." + digitsOnly.padStart(6, '0');
      }
      return parseFloat(s) || 0;
    }
  }

  return parseFloat(s) || 0;
};

const getValMoneyMaint = (row: any, type: 'AVULSO' | 'ESTOQUE'): number => {
  if (!row) return 0;
  const keys = Object.keys(row);
  
  // Specific targets based on known ERP schemas
  const avulsoTargets = [
    'VALORNFSERVICO', 'valornfservico', 'vlr_total', 'VLR_TOTAL', 
    'VALOR_AVULSO', 'Valor Avulso', 'VALORTOTALNF', 'VALOR_NF', 
    'TOTAL_NF', 'VALOR_BRUTO', 'VLR_LIQUIDO', 'VALOR_TOTAL_NF'
  ];
  
  const estoqueTargets = [
    'VALORITEM', 'valoritem', 'Valor Estoque', 'VALOR_ESTOQUE', 
    'VALORTOTAL', 'VALOR_ESTOQUENO', 'TOTAL_ITEM', 'VALOR_MOVIMENTACAO',
    'VLR_ESTOQUE', 'VALOR_ESTOQUENO'
  ];

  // Let's use a unified search loop with priorities.
  const searchTargets = type === 'AVULSO' ? avulsoTargets : estoqueTargets;
  for (const tk of searchTargets) {
    const normTk = normalizeKey(tk);
    const foundKey = keys.find(k => normalizeKey(k) === normTk);
    if (foundKey && row[foundKey] !== undefined && row[foundKey] !== null && row[foundKey] !== '') {
      const val = parseMoney(row[foundKey]);
      if (val !== 0) return val;
    }
  }

  // Fallback to general keys if specific ones not found
  const fallbackKeys = [
    'VALOR_TOTAL', 'VALOR_LIQUIDO', 'VALOR_BRUTO', 'VALOR', 'TOTAL', 'VLR_TOTAL', 'TOTAL_LIQUIDO'
  ];
  for (const tk of fallbackKeys) {
    const normTk = normalizeKey(tk);
    const foundKey = keys.find(k => normalizeKey(k) === normTk);
    if (foundKey && row[foundKey] !== undefined && row[foundKey] !== null && row[foundKey] !== '') {
      const val = parseMoney(row[foundKey]);
      if (val !== 0) return val;
    }
  }

  // Last resort: qty * unitPrice
  const qtyKeys = ['QTDEITEM', 'QTDE_MOVTO', 'QUANTIDADE', 'QTDE', 'QTD', 'QUANT'];
  const unitPriceKeys = ['PRECO_UNITARIO', 'VLR_UNITARIO', 'VALOR_UNITARIO', 'CUSTO_UNITARIO', 'VALOR_UNIT', 'PRECO_UNIT'];
  
  let qty = 0;
  for (const qk of qtyKeys) {
    const foundKey = keys.find(k => normalizeKey(k) === normalizeKey(qk));
    if (foundKey && row[foundKey]) {
      qty = parseMoney(row[foundKey]);
      break;
    }
  }
  let unitPrice = 0;
  for (const upk of unitPriceKeys) {
    const foundKey = keys.find(k => normalizeKey(k) === normalizeKey(upk));
    if (foundKey && row[foundKey]) {
      unitPrice = parseMoney(row[foundKey]);
      break;
    }
  }
  if (qty > 0 && unitPrice > 0) return qty * unitPrice;
  return 0;
};

