const normalizeFrotaManutencao = (val: any) => {
  if (val === null || val === undefined || val === '') return 'Sem Veic';
  let s = val.toString().trim();
  s = s.replace(/\.0$/, ''); 
  
  const lower = s.toLowerCase();
  if (
    lower === 'sem veiculo' || lower === 'sem veículo' || lower === 'sem veic' || 
    lower === 's/veic' || lower === 'sem placa' || lower === 's/placa' || 
    lower === 'n/a' || lower === 'null' || lower === 'undefined' || lower === 'n' || 
    lower === 'geral' || lower === 'diversos' || lower === 'matriz' || lower === 'oficina' ||
    lower === 'almoxarifado' || lower === 'predio' || lower === 'prédio' ||
    s === '' || s === '0' || s === '00' || s === '000' || s === '0000'
  ) {
    return 'Sem Veic';
  }

  // Handle formats like "9005030 / DEU5A30", "9005030 - DEU5A30" or "9005030/DEU-5A30"
  if (s.includes('/') || (s.includes(' - ') && !/^[A-Z]{3}-\d[A-Z0-9]\d{2}$/i.test(s))) {
    const splitParts = s.split(/[\/\-]/).map(p => p.trim()).filter(Boolean);
    for (const part of splitParts) {
      const partUpper = part.toUpperCase();
      if (/^\d+$/.test(part) || FLEET_LOOKUP.has(partUpper)) {
        s = part;
        break;
      }
    }
  }

  const sUpper = s.toUpperCase().trim();
  if (FLEET_LOOKUP.has(sUpper)) return FLEET_LOOKUP.get(sUpper)!;
  
  if (/^0+\d+$/.test(sUpper)) {
    const withoutZero = sUpper.replace(/^0+/, '');
    if (FLEET_LOOKUP.has(withoutZero)) return FLEET_LOOKUP.get(withoutZero)!;
    if (withoutZero === '0' || withoutZero === '') return 'Sem Veic';
    return withoutZero;
  }
  
  return sUpper;
};

