  const isFuelTypeMatching = (fuelType: string | undefined | null, selectedFilters: string[]): boolean => {
    if (!selectedFilters || selectedFilters.length === 0) return true;
    if (!fuelType) return false;

    const rawFuel = fuelType.trim().toUpperCase();
    if (!rawFuel) return false;

    if (selectedFilters.some(sf => sf.trim().toUpperCase() === rawFuel)) return true;

    for (const filter of selectedFilters) {
      const normFilter = filter.trim().toUpperCase();
      if (normFilter === rawFuel) return true;

      const isFilterDiesel = normFilter.includes('DIESEL') || normFilter.includes('S10') || normFilter.includes('S500') || normFilter.includes('S-10') || normFilter.includes('S-500');
      const isFuelDiesel = rawFuel.includes('DIESEL') || rawFuel.includes('S10') || rawFuel.includes('S500') || rawFuel.includes('S-10') || rawFuel.includes('S-500');
      if (isFilterDiesel) {
        if (isFuelDiesel) return true;
        continue;
      }

      const isFilterGasolina = normFilter.includes('GASOLINA') || normFilter.includes('G-GRID');
      const isFuelGasolina = rawFuel.includes('GASOLINA') || rawFuel.includes('G-GRID') || rawFuel.includes('FLEX');
      if (isFilterGasolina) {
        if (isFuelGasolina) return true;
        continue;
      }

      const isFilterEtanol = normFilter.includes('ETANOL') || normFilter.includes('ALCOOL') || normFilter.includes('ÁLCOOL');
      const isFuelEtanol = rawFuel.includes('ETANOL') || rawFuel.includes('ALCOOL') || rawFuel.includes('ÁLCOOL') || rawFuel.includes('FLEX');
      if (isFilterEtanol) {
        if (isFuelEtanol) return true;
        continue;
      }

      if (rawFuel === normFilter) return true;
    }

    return false;
  };

  const isServicoMatching = (servico: string | undefined | null, selectedFilters: string[]): boolean => {
    if (!selectedFilters || selectedFilters.length === 0) return true;
    if (!servico) return false;
    const rawServico = servico.trim().toUpperCase();
    if (!rawServico) return false;
    return selectedFilters.some(sf => sf.trim().toUpperCase() === rawServico);
  };

  const getVehiclePeriodLiters = (placa: string, periodType: 'filtro' | 'mes' | 'q1' | 'q2' | 'none', origLiters: number) => {
    if (periodType === 'filtro') return origLiters;
    if (periodType === 'none') return 0;

    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    let sum = 0;
    
    for (let i = 0; i < combData.length; i++) {
       const f = combData[i];
       const { plate: fPlate } = getVehicleID(f, 'fuel');
       const fPlaca = fPlate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
       if (fPlaca !== normPlaca) continue;

       const d = parseDataAuto(f.DATA);
       if (!d) continue;

       const rowYear = String(d.getFullYear());
       const rowMonth = String(d.getMonth() + 1).padStart(2, '0');

       const matchYear = filterYear.length === 0 || filterYear.includes(rowYear);
       const matchMonth = filterMonth.length === 0 || filterMonth.includes(rowMonth);

       if (!matchYear || !matchMonth) continue;

       if (filterCombustivel.length > 0 && f.TIPO_COMBUSTIVEL && !isFuelTypeMatching(f.TIPO_COMBUSTIVEL, filterCombustivel)) continue;
       if (filterServico.length > 0 && f.SERVICO && !isServicoMatching(f.SERVICO, filterServico)) continue;

      if (periodType === 'mes') {
        sum += f.LITROS || 0;
      } else if (periodType === 'q1') {
        if (d.getDate() <= 15) {
          sum += f.LITROS || 0;
        }
      } else if (periodType === 'q2') {
        if (d.getDate() > 15) {
          sum += f.LITROS || 0;
        }
      }
    }
    return sum;
  };

  const getVehiclePeriodValor = (placa: string, periodType: 'filtro' | 'mes' | 'q1' | 'q2' | 'none', origValor: number) => {
    if (periodType === 'filtro') return origValor;
    if (periodType === 'none') return 0;

    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    let sum = 0;
    
    for (let i = 0; i < combData.length; i++) {
       const f = combData[i];
       const { plate: fPlate } = getVehicleID(f, 'fuel');
       const fPlaca = fPlate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
       if (fPlaca !== normPlaca) continue;

       const d = parseDataAuto(f.DATA);
       if (!d) continue;

       const rowYear = String(d.getFullYear());
       const rowMonth = String(d.getMonth() + 1).padStart(2, '0');

       const matchYear = filterYear.length === 0 || filterYear.includes(rowYear);
       const matchMonth = filterMonth.length === 0 || filterMonth.includes(rowMonth);

       if (!matchYear || !matchMonth) continue;

       if (filterCombustivel.length > 0 && f.TIPO_COMBUSTIVEL && !isFuelTypeMatching(f.TIPO_COMBUSTIVEL, filterCombustivel)) continue;
       if (filterServico.length > 0 && f.SERVICO && !isServicoMatching(f.SERVICO, filterServico)) continue;

      if (periodType === 'mes') {
        sum += f.VALOR || 0;
      } else if (periodType === 'q1') {
        if (d.getDate() <= 15) {
          sum += f.VALOR || 0;
        }
      } else if (periodType === 'q2') {
        if (d.getDate() > 15) {
          sum += f.VALOR || 0;
        }
      }
    }
    return sum;
  };

  const getVehiclePeriodLitersForMonth = (placa: string, yearStr: string, monthStr: string, periodType: 'filtro' | 'mes' | 'q1' | 'q2' | 'none', origLiters: number) => {
    if (periodType === 'filtro' || periodType === 'mes') return origLiters;
    if (periodType === 'none') return 0;

    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    let sum = 0;
    
    for (let i = 0; i < combData.length; i++) {
       const f = combData[i];
       const { plate: fPlate } = getVehicleID(f, 'fuel');
       const fPlaca = fPlate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
       if (fPlaca !== normPlaca) continue;

       const d = parseDataAuto(f.DATA);
       if (!d) continue;

       const rowYear = String(d.getFullYear());
       const rowMonth = String(d.getMonth() + 1).padStart(2, '0');

       if (rowYear !== yearStr || rowMonth !== monthStr) continue;
       if (filterCombustivel.length > 0 && f.TIPO_COMBUSTIVEL && !isFuelTypeMatching(f.TIPO_COMBUSTIVEL, filterCombustivel)) continue;
       if (filterServico.length > 0 && f.SERVICO && !isServicoMatching(f.SERVICO, filterServico)) continue;

       if (periodType === 'q1') {
         if (d.getDate() <= 15) {
           sum += f.LITROS || 0;
         }
       } else if (periodType === 'q2') {
         if (d.getDate() > 15) {
           sum += f.LITROS || 0;
         }
       }
    }
    return sum;
  };

  const getVehiclePeriodValorForMonth = (placa: string, yearStr: string, monthStr: string, periodType: 'filtro' | 'mes' | 'q1' | 'q2' | 'none', origValor: number) => {
    if (periodType === 'filtro' || periodType === 'mes') return origValor;
    if (periodType === 'none') return 0;

    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    let sum = 0;
    
    for (let i = 0; i < combData.length; i++) {
       const f = combData[i];
       const { plate: fPlate } = getVehicleID(f, 'fuel');
       const fPlaca = fPlate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
       if (fPlaca !== normPlaca) continue;

       const d = parseDataAuto(f.DATA);
       if (!d) continue;

       const rowYear = String(d.getFullYear());
       const rowMonth = String(d.getMonth() + 1).padStart(2, '0');

       if (rowYear !== yearStr || rowMonth !== monthStr) continue;
       if (filterCombustivel.length > 0 && f.TIPO_COMBUSTIVEL && !isFuelTypeMatching(f.TIPO_COMBUSTIVEL, filterCombustivel)) continue;
       if (filterServico.length > 0 && f.SERVICO && !isServicoMatching(f.SERVICO, filterServico)) continue;

       if (periodType === 'q1') {
         if (d.getDate() <= 15) {
           sum += f.VALOR || 0;
         }
       } else if (periodType === 'q2') {
         if (d.getDate() > 15) {
           sum += f.VALOR || 0;
         }
       }
    }
    return sum;
  };

  const getAdjustmentForVehicleAndPeriod = (placa: string, yearStr?: string, monthStr?: string) => {
    if (!placa) return null;
    const cleanPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    
    // Find vehicle's fleet number & canonical plate
    const mappingObj = CORINGA_MAPPING.find(
      m => m.sistema.toUpperCase().replace(/[^A-Z0-9]/g, '') === cleanPlaca || 
           m.coringa.toUpperCase().replace(/[^A-Z0-9]/g, '') === cleanPlaca || 
           String(m.frota).trim().replace(/[^A-Z0-9]/g, '') === cleanPlaca
    );
    const frotaClean = mappingObj ? String(mappingObj.frota).trim().replace(/[^A-Z0-9]/g, '') : '';
    const sistemaClean = mappingObj ? mappingObj.sistema.toUpperCase().replace(/[^A-Z0-9]/g, '') : '';
    
    const candidateIds = new Set<string>([cleanPlaca]);
    if (frotaClean) candidateIds.add(frotaClean);
    if (sistemaClean) candidateIds.add(sistemaClean);

    // Also check in veiculoData
    const vMatch = veiculoData.find(v => {
      const vp = (v.PLACA || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
      const vf = String(v.FROTA || '').trim().replace(/[^A-Z0-9]/g, '');
      return vp === cleanPlaca || vf === cleanPlaca;
    });
    if (vMatch) {
      if (vMatch.PLACA) candidateIds.add(vMatch.PLACA.trim().toUpperCase().replace(/[^A-Z0-9]/g, ''));
      if (vMatch.FROTA) candidateIds.add(String(vMatch.FROTA).trim().replace(/[^A-Z0-9]/g, ''));
    }

    const candidateMonths: string[] = [];
    if (monthStr && monthStr !== 'ALL') {
      candidateMonths.push(monthStr);
      const mNum = parseInt(monthStr, 10);
      if (!isNaN(mNum)) {
        candidateMonths.push(String(mNum));
        candidateMonths.push(String(mNum).padStart(2, '0'));
      }
    }
    candidateMonths.push('ALL');

    const candidateYears = [yearStr || 'ALL', 'ALL'];

    for (const id of candidateIds) {
      for (const y of candidateYears) {
        for (const m of candidateMonths) {
          const k = `${id}_${y}_${m}`;
          if (crossMonthAdjustments[k]) return crossMonthAdjustments[k];
        }
      }
    }

    // Direct key check fallback across all entries in crossMonthAdjustments
    for (const [adjKey, adjVal] of Object.entries(crossMonthAdjustments)) {
      const parts = adjKey.split('_');
      if (parts.length >= 3) {
        const [kPlaca, kYear, kMonth] = parts;
        if (candidateIds.has(kPlaca)) {
          const yMatch = kYear === 'ALL' || !yearStr || yearStr === 'ALL' || kYear === yearStr;
          const mMatch = kMonth === 'ALL' || !monthStr || monthStr === 'ALL' || candidateMonths.includes(kMonth);
          if (yMatch && mMatch) return adjVal;
        }
      }
    }

    return null;
  };

  const getAdjustedMonthlyValues = (
    placa: string, 
    yearStr: string, 
    monthStr: string, 
    origLiters: number, 
    origValor: number, 
    kmProdutivo: number
  ) => {
    const customAdj = getAdjustmentForVehicleAndPeriod(placa, yearStr, monthStr);
    
    if (customAdj && customAdj.isOverlap) {
      const basePeriodType = customAdj.basePeriodType || (customAdj.includeOriginalMonth !== false ? 'filtro' : 'none');
      const baseL = getVehiclePeriodLitersForMonth(placa, yearStr, monthStr, basePeriodType, origLiters);
      const baseVal = getVehiclePeriodValorForMonth(placa, yearStr, monthStr, basePeriodType, origValor);
      
      const extraFuelings = getAvailableFuelingsForVehicle(placa, true);
      const selectedFuelingKeys = customAdj.selectedFuelingKeys || [];
      
      const selectedLitros = extraFuelings
        .filter(item => {
          const itemKey = `${item.f.DATA}_${item.f.LITROS}_${item.f.VALOR}_${item.originalIndex}`;
          return selectedFuelingKeys.includes(itemKey);
        })
        .reduce((sum, item) => sum + item.f.LITROS, 0);
        
      const selectedValor = extraFuelings
        .filter(item => {
          const itemKey = `${item.f.DATA}_${item.f.LITROS}_${item.f.VALOR}_${item.originalIndex}`;
          return selectedFuelingKeys.includes(itemKey);
        })
        .reduce((sum, item) => sum + item.f.VALOR, 0);
        
      let litros = baseL + selectedLitros;
      let valor = baseVal + selectedValor;
      
      if (customAdj.adjustedLitros !== undefined && customAdj.adjustedLitros > 0) {
        const manualLitros = customAdj.adjustedLitros;
        const ratio = litros > 0 ? (manualLitros / litros) : 1;
        litros = manualLitros;
        valor = valor * ratio;
      }
      
      litros = Math.round(litros * 100) / 100;
      valor = Math.round(valor * 100) / 100;
      
      let kml = 0;
      if (customAdj.adjustedKml !== undefined && customAdj.adjustedKml > 0) {
        kml = customAdj.adjustedKml;
        if (customAdj.adjustedLitros === undefined || customAdj.adjustedLitros === 0) {
          litros = kml > 0 ? Math.round((kmProdutivo / kml) * 100) / 100 : litros;
        }
      } else {
        kml = litros > 0 ? kmProdutivo / litros : 0;
      }
      
      return { litros, valor, kml, isOverlapAdjusted: true };
    }
    
    // Unadjusted fallback
    return {
      litros: origLiters,
      valor: origValor,
      kml: origLiters > 0 ? kmProdutivo / origLiters : 0,
      isOverlapAdjusted: false
    };
  };

  const getAdjustmentKey = (placa: string) => {
    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    const yr = filterYear.length > 0 ? filterYear.join('-') : 'ALL';
    const mo = filterMonth.length > 0 ? filterMonth.join('-') : 'ALL';
    return `${normPlaca}_${yr}_${mo}`;
  };

  const getAvailableFuelingsForVehicle = (placa: string, ignoreMonthAndPeriodFilters: boolean = false) => {
    const normPlaca = placa.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    
    // Find vehicle's fleet number from CORINGA_MAPPING or veiculoData
    const targetMappingObj = CORINGA_MAPPING.find(
      m => m.sistema.toUpperCase().replace(/[^A-Z0-9]/g, '') === normPlaca || 
           m.coringa.toUpperCase().replace(/[^A-Z0-9]/g, '') === normPlaca || 
           String(m.frota).trim().replace(/[^A-Z0-9]/g, '') === normPlaca
    );
    let targetFrota = targetMappingObj ? String(targetMappingObj.frota).trim() : '';
    if (!targetFrota) {
      const vMatch = veiculoData.find(v => {
        const vp = (v.PLACA || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
        const vf = String(v.FROTA || '').trim().replace(/[^A-Z0-9]/g, '');
        return vp === normPlaca || vf === normPlaca;
      });
      if (vMatch && vMatch.FROTA) targetFrota = String(vMatch.FROTA).trim();
    }

    return combData
      .map((f, originalIndex) => ({ f, originalIndex }))
      .filter(({ f }) => {
        // Resolve canonical plate and fleet using same layout helper
        const fIdInfo = getVehicleID(f, 'fuel');
        const fCanonical = fIdInfo.plate.trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
        const fFrota = String(fIdInfo.frota || f.FROTA || '').trim();
        const fPlacaRaw = (f.PLACA || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');

        let isMatch = (fCanonical === normPlaca) || (fPlacaRaw === normPlaca);
        
        if (!isMatch && targetFrota && targetFrota !== 'N/A' && targetFrota !== '') {
          if (targetFrota === fFrota) {
            isMatch = true;
          }
        }

        if (!isMatch) return false;

        const d = parseDataAuto(f.DATA);
        if (!d) return false;

        if (!ignoreMonthAndPeriodFilters) {
          const rowYear = String(d.getFullYear());
          const rowMonth = String(d.getMonth() + 1).padStart(2, '0');
          
          const matchYear = filterYear.length === 0 || filterYear.includes(rowYear);
          if (!matchYear) return false;

          const matchMonth = filterMonth.length === 0 || filterMonth.includes(rowMonth);
          if (!matchMonth) return false;

          if (filterQuinzena.length > 0) {
            const q = d.getDate() <= 15 ? "1" : "2";
            if (!filterQuinzena.includes(q)) return false;
          }
          if (filterSemana.length > 0) {
            const s = f.semanaAno || String(Math.ceil(d.getDate() / 7));
            if (!filterSemana.includes(s)) return false;
          }

          if (filterCombDateStart) {
            const startLimit = parseDataAuto(filterCombDateStart);
            if (startLimit && d < startLimit) return false;
          }
          if (filterCombDateEnd) {
            const endLimit = parseDataAuto(filterCombDateEnd);
            if (endLimit && d > endLimit) return false;
          }

          if (filterCombustivel.length > 0 && f.TIPO_COMBUSTIVEL && !isFuelTypeMatching(f.TIPO_COMBUSTIVEL, filterCombustivel)) return false;
          if (filterServico.length > 0 && f.SERVICO && !isServicoMatching(f.SERVICO, filterServico)) return false;
        }
        
        return true;
      });
  };

