      const response = await fetchWithProxyFallback(url);
      const csvText = await response.text();
      
      if (csvText.toLowerCase().includes('rate exceeded') || csvText.trim() === 'Rate exceeded.') {
        console.error("Erro: Limite de cota do Google Sheets excedido (Rate exceeded).");
        throw new Error('Limite de requisições do Google Sheets excedido (Rate exceeded). Por favor, aguarde alguns instantes e tente novamente.');
      }
      
      if (csvText.includes('<!DOCTYPE html>')) {
        console.error("Erro: Planilha retornou HTML. Provavelmente é privada.");
        throw new Error('Planilha PRIVADA ou Não Encontrada');
      }
      
      console.log("KM CSV Content length:", csvText.length);
      console.log("KM CSV Content preview:", csvText.substring(0, 200));

      let data: any[] = [];
      if (csvText.trim().startsWith('{') || csvText.trim().startsWith('[')) {
        try {
          data = JSON.parse(csvText);
        } catch (e) {
          const workbook = XLSX.read(csvText, { type: 'string', cellDates: true });
          const sheet = workbook.Sheets[workbook.SheetNames[0]];
          data = XLSX.utils.sheet_to_json(sheet, { raw: true });
        }
      } else {
        const results = Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          dynamicTyping: false,
          transformHeader: (h) => h.trim().replace(/^\uFEFF/, '')
        });
        data = results.data;
      }

      if (!data || data.length === 0) {
        console.warn("Nenhum dado extraído pelo PapaParse. Tentando XLSX...");
        try {
          const workbook = XLSX.read(csvText, { type: 'string', cellDates: true });
          const sheet = workbook.Sheets[workbook.SheetNames[0]];
          data = XLSX.utils.sheet_to_json(sheet, { raw: true });
        } catch(e) {
          console.error("Erro ao tentar XLSX fallback:", e);
        }
      }
      
      if (!data || data.length === 0) {
        throw new Error("Nenhum dado de KM encontrado na planilha.");
      }

      const headers = Object.keys(data[0]);
      console.log("--- DEBUG KM SHEET ---");
