        const kmFinRaw = getVal(row, 'KM_FINAL', 'KM FINAL', 'KM_FIN', 'KM FIN', 'ODOMETRO_FINAL', 'ODOMETRO FINAL', 'KM_FIM', 'KM FIM', 'KM_ATUAL', 'KM ATUAL', 'KM_ATU', 'KM ATU', 'ODÔMETRO FINAL', 'KM FINAL (ODÔMETRO)', 'KM_FINAL_ODOMETRO', 'KM FINAL ODOMETRO', 'KM_ODOMETRO_FINAL', 'KM ODOMETRO FINAL', 'KM_FIM_ODOMETRO', 'KM FIM ODOMETRO', 'KM_CHEGADA', 'KM CHEGADA', 'KM_RETORNO', 'KM RETORNO', 'KM_FECHAMENTO', 'KM FECHAMENTO', 'KM_FIM_VIAGEM', 'KM FIM VIAGEM');
        const kmProdRaw = getVal(row, 'KM_PRODUTIVO', 'KM PRODUTIVO', 'KM_PROD', 'KM PROD', 'KM_PERCORRIDO', 'KM PERCORRIDO', 'DISTANCIA', 'DISTÂNCIA', 'KM_PROD_TOTAL', 'KM Produtivo (Planilha)', 'Soma de KM Produtivo', 'KM_PROD_PLANILHA', 'KM_PRODUTIVO_REAL', 'KM PRODUTIVO REAL', 'KM_PERC', 'KM PERC', 'KM', 'KILOMETRAGEM', 'KM_RODADO', 'KM RODADO', 'DIST_PERC', 'DIST PERC', 'KM_VIAGEM', 'KM VIAGEM');
        const kmTotalRaw = getVal(row, 'KM_TOTAL', 'KM TOTAL', 'KM_RODADO_TOTAL', 'KM RODADO TOTAL', 'KM_PERCORRIDO_TOTAL', 'KM PERCORRIDO TOTAL', 'DISTANCIA_TOTAL', 'DISTÂNCIA TOTAL');

        const kmIni = parseNumeric(kmIniRaw, true);
        const kmFin = parseNumeric(kmFinRaw, true);
        const kmProd = (kmProdRaw !== undefined && kmProdRaw !== null && String(kmProdRaw).trim() !== "") ? parseNumeric(kmProdRaw, true) : -1;
        const kmTotal = (kmTotalRaw !== undefined && kmTotalRaw !== null && String(kmTotalRaw).trim() !== "") ? parseNumeric(kmTotalRaw, true) : (kmFin > kmIni && kmIni > 0 ? kmFin - kmIni : 0);
        
        const operacao = normalizeOperacao(getVal(row, 'OPERACAO', 'OPERAÇÃO', 'CENTRO_CUSTO', 'CENTRO CUSTO', 'CC', 'PROJETO', 'LINHA', 'SERVICO', 'SERVIÇO', 'ROTA', 'MARGEM', 'OPERACAO_KM', 'OPERACAO KM', 'NOME_OPERACAO', 'NOME OPERACAO', 'DESC_OPERACAO', 'DESC OPERACAO', 'UNIDADE', 'FILIAL'));
        const frota = normalizeFrota(getVal(row, 'FROTA', 'Frota', 'PREFIXO', 'CARRO', 'NUMERO_FROTA', 'NUMERO FROTA')) || 'N/A';
        const placa = String(getVal(row, 'PLACA', 'VEICULO', 'VEÍCULO', 'PREFIXO', 'FROTA', 'CARRO', 'IDENTIFICACAO', 'PLACA_VEICULO', 'PLACA VEICULO') || '').trim();

